<div class="page-heading"><div><span class="eyebrow"><?=e($part['sku'])?></span><h1><?=e($part['name'])?></h1><p class="muted">Stok minimum <?=e($part['minimum_stock'].' '.$part['unit'])?> · Harga beli <?=e(money($part['purchase_price']))?> · Harga jual <?=e(money($part['sale_price']))?></p></div><?php $deletionKind='part'; $deletionRecord=$part; require ROOT.'/views/deletion-actions.php'; ?></div><div class="inventory-top"><section class="panel compact"><span class="eyebrow">STOK TERSEDIA</span><p class="inventory-balance"><?=e($part['stock'])?> <small><?=e($part['unit'])?></small></p><?php if((int)$part['stock']===0): ?><span class="badge red">Stok habis</span><?php elseif($part['stock']<=$part['minimum_stock']): ?><span class="badge amber">Stok menipis</span><?php else: ?><span class="badge green">Stok tersedia</span><?php endif; ?></section><?php if($part['deleted_at']===null): ?><section class="panel form-panel"><h2>Catat stok masuk</h2><form method="post" class="inline-form"><?=csrf()?><input type="hidden" name="action" value="receive"><input type="hidden" name="operation_key" value="<?=e($data['operation_key'])?>"><?php input_field('quantity','Jumlah masuk',$data,'number',true,'min="1" max="1000000000" step="1"'); input_field('reason','Keterangan / sumber',$data,'text',true,'maxlength="180" placeholder="Pembelian / penerimaan barang"'); ?><button class="button">Tambah stok</button></form></section><?php endif; ?></div><?php if($part['deleted_at']===null): ?><section class="panel form-panel" id="stock-adjustment"><h2>Sesuaikan stok</h2><form method="post" class="form-grid"><?=csrf()?><input type="hidden" name="action" value="adjust"><input type="hidden" name="stock_key" value="<?=e($data['stock_key'])?>"><input type="hidden" name="stock_revision" value="<?=e($data['stock_revision'])?>"><?php input_field('stock_quantity','Stok tersedia yang benar',$data,'number',true,'min="0" max="1000000000" step="1"'); input_field('stock_reason','Alasan penyesuaian',$data,'text',true,'maxlength="180" placeholder="Hasil hitung, barang rusak, atau koreksi stok"'); ?><p class="form-note full">Isi 0 untuk stok habis. Perubahan dicatat pada histori.</p><div class="form-actions full"><button class="button" type="submit">Simpan penyesuaian stok</button><a class="text-link" href="<?=e(url('part',['id'=>$part['id']]))?>">Muat ulang</a></div></form></section><?php endif; ?><section class="panel"><div class="panel-heading"><div><h2>Histori pergerakan stok</h2></div></div><?php if(!$movements): ?><div class="empty"><h3>Belum ada pergerakan stok</h3></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>WAKTU / ADMIN</th><th>KETERANGAN</th><th>PERUBAHAN</th><th>SALDO</th><th>SERVIS</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?=e($m['created_at'])?><small><?=e($m['actor_phone'])?></small></td><td class="wrap-cell"><?=e($m['reason'])?></td><td class="<?= $m['delta']>0?'stock-positive':'stock-low' ?>"><?= $m['delta']>0?'+':'' ?><?=e($m['delta'])?></td><td><?=e($m['balance_after'])?></td><td><?php if($m['service_order_id']): ?><a class="table-primary" href="<?=e(url('order',['id'=>$m['service_order_id']]))?>"><?=e($m['invoice_number'])?></a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php pagination($p,count($movements),'part',['id'=>$part['id']]); ?></section>
